#!/usr/bin/env bash
cd "$(git rev-parse --show-toplevel)"
# set -euo pipefail

# Expects animated work_*.blend files
# (outputs/blender/work_*.blend generated by run_animate*.sh)

FRAME_START=1
FRAME_END=10
COUNT=1
ALL=0
ALL_FRAMES=0
DIR_PATH="outputs/animate_temp/transformedcsv"
BLEND_DIR="outputs/blender"
OUTPUT_DIR="outputs/render"
RESOLUTION=""
CAM_NAMES=()
GPU_ARGS=()

while [[ $# -gt 0 ]]; do
  case "$1" in
    --help|-h)
      cat <<EOF
Usage: $(basename "$0") [OPTIONS]

Options:
  --cam <name>        Camera name (repeatable, default: Camera_C Camera_L Camera_R)
  --count <n>         Max number of CSVs to process (default: 1)
  --all-csv           Process all CSVs
  --frame-start <n>   Start frame (default: 1)
  --frame-end <n>     End frame (default: 10)
  --csv-dir <dir>     CSV directory (default: outputs/animate_temp/transformedcsv)
  --blend-dir <dir>   Directory of blend files (default: outputs/blender)
  --output-dir <dir>  Output directory for renders (default: outputs/render)
  --resolution <WxH>  Resolution (e.g. 1920x1080; default: value in blend file)
  --gpu <ids>         GPU IDs to use (comma-separated, e.g. 0,1,2)
  --all-frames        Process all frames in the CSV (overrides --frame-start/--frame-end)
  -h, --help          Show this help
EOF
      exit 0;;
    --cam)        CAM_NAMES+=("$2");  shift 2;;
    --count)      COUNT="$2";         shift 2;;
    --all-csv)    ALL=1;              shift;;
    --frame-start) FRAME_START="$2"; shift 2;;
    --frame-end)   FRAME_END="$2";   shift 2;;
    --csv-dir)    DIR_PATH="$2";      shift 2;;
    --blend-dir)  BLEND_DIR="$2";    shift 2;;
    --output-dir) OUTPUT_DIR="$2";        shift 2;;
    --resolution) RESOLUTION="$2";        shift 2;;
    --gpu)        GPU_ARGS=(--gpu "$2");  shift 2;;
    --all-frames) ALL_FRAMES=1;          shift;;
    *) echo "Unknown arg: $1"; exit 1;;
  esac
done

if [[ ${#CAM_NAMES[@]} -eq 0 ]]; then
  CAM_NAMES=("Camera_C" "Camera_L" "Camera_R")
fi

cnt=0

for csv in "$DIR_PATH"/*.csv; do
  echo 'start' $csv
  ((cnt++))
  if [[ $ALL -eq 0 ]] && (( cnt > COUNT )); then
    echo "Reached CSV processing limit (${COUNT}); exiting"
    break
  fi
  echo $cnt
  name=$(basename "$csv" .csv)

  if [[ $ALL_FRAMES -eq 1 ]]; then
    # i_frame is 0-based and Blender frames are 1-based, so the row count excluding the header is the end frame
    FRAME_START=1
    FRAME_END=$(( $(wc -l < "$csv") - 1 ))
    echo "  -> All frames: ${FRAME_START}-${FRAME_END}"
  fi

  mkdir -p "${OUTPUT_DIR}/${name}"

  for CAM_NAME in "${CAM_NAMES[@]}"; do
    echo "  -> Render camera: ${CAM_NAME}"

    python scripts/05_create_digital_twin/render_parallel.py \
      --blend "${BLEND_DIR}/work_${name}.blend" \
      --camera "$CAM_NAME" \
      --entire_start "$FRAME_START" \
      --entire_end "$FRAME_END" \
      --out "${OUTPUT_DIR}/${name}/${CAM_NAME}" \
      --prefix "${name}_${CAM_NAME}_" \
      ${RESOLUTION:+--resolution "$RESOLUTION"} \
      "${GPU_ARGS[@]}"
  done
done
